solution.invoice.js:
// Each line: { price, qty }. Returns the total in dollars, working in whole cents.
const cents = (x) => Math.round(x * 100);

export function total(lines) {
  let sum = 0;
  for (const l of lines) sum += cents(l.price) * l.qty;
  return sum / 100;
}

export function withGst(amount) {
  return Math.round(cents(amount) * 1.1) / 100;
}
